import XCTest
#if canImport(CryptoKit)
import CryptoKit
#else
import Crypto
#endif
@testable import Matilde

/// Checks the Swift implementation against docs/sync-vectors/v1.json, generated by an independent
/// Python implementation (scripts/sync-vectors.py). Future clients (web, iOS) check the same file.
final class SyncVectorTests: XCTestCase {
    private struct Vectors: Decodable {
        struct Key: Decodable { var keyId: Int; var key: String; var keyCheck: String }
        struct Padding: Decodable { var length: Int; var padded: Int }
        struct Record: Decodable { var keyId: Int; var recordId: String; var type: Int; var hlc: String; var deleted: Bool; var salt: String; var nonce: String; var plaintext: String; var envelope: String }
        struct Field: Decodable { var keyId: Int; var purpose: String; var subject: String; var salt: String; var nonce: String; var plaintext: String; var envelope: String }
        struct Slot: Decodable { var kind: String; var slotId: String; var keyId: Int; var secret: String; var salt: String; var nonce: String; var plaintext: String; var wrappedKey: String }
        struct Blob: Decodable { var blobId: String; var key: String; var chunkSize: Int; var noncePrefix: String; var plaintextSeed: String; var plaintextLength: Int; var plaintextSha256: String; var blob: String }
        struct Code: Decodable { var key: String; var code: String }
        var userId: String
        var accountKeys: [Key]
        var padding: [Padding]
        var records: [Record]
        var fields: [Field]
        var slots: [Slot]
        var blobs: [Blob]
        var recoveryCodes: [Code]
    }

    private func load() throws -> Vectors {
        // apps/macos/Tests/MatildeTests/<file> -> repository root, where the shared vectors live.
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { url.deleteLastPathComponent() }
        url.appendPathComponent("docs/sync-vectors/v1.json")
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    private func bytes(_ base64: String) -> Data { Data(base64Encoded: base64)! }

    private func ring(_ vectors: Vectors) throws -> AccountKeyRing {
        let keys = try vectors.accountKeys.map { try AccountKey(id: $0.keyId, bytes: bytes($0.key)) }
        return try AccountKeyRing(userId: vectors.userId, current: keys.last!, previous: Array(keys.dropLast()))
    }

    /// Same deterministic bytes as `seed` in scripts/sync-vectors.py.
    private func seed(_ label: String, _ count: Int) -> Data {
        var out = Data()
        var counter = 0
        while out.count < count {
            out.append(contentsOf: SHA256.hash(data: Data("matilde-test-vector/\(label)/\(counter)".utf8)))
            counter += 1
        }
        return Data(out.prefix(count))
    }

    func testKeyChecks() throws {
        let vectors = try load()
        for vector in vectors.accountKeys {
            let key = try AccountKey(id: vector.keyId, bytes: bytes(vector.key))
            XCTAssertEqual(key.check.base64EncodedString(), vector.keyCheck)
        }
    }

    func testPadding() throws {
        for vector in try load().padding {
            XCTAssertEqual(SyncPadding.paddedLength(for: vector.length), vector.padded, "length \(vector.length)")
        }
    }

    func testRecords() throws {
        let vectors = try load()
        let ring = try ring(vectors)
        XCTAssertFalse(vectors.records.isEmpty)
        for vector in vectors.records {
            let context = SyncRecordContext(userId: vectors.userId, recordId: vector.recordId, type: vector.type, hlc: vector.hlc, deleted: vector.deleted)
            let sealed = try SyncRecordCrypto.seal(bytes(vector.plaintext), context: context, key: ring.key(id: vector.keyId), salt: bytes(vector.salt), nonce: bytes(vector.nonce))
            XCTAssertEqual(sealed.base64EncodedString(), vector.envelope, vector.recordId)
            XCTAssertEqual(try SyncRecordCrypto.open(bytes(vector.envelope), context: context, keyId: vector.keyId, ring: ring), bytes(vector.plaintext))
        }
    }

    func testFields() throws {
        let vectors = try load()
        let all = try ring(vectors)
        for vector in vectors.fields {
            let ring = try AccountKeyRing(userId: vectors.userId, current: all.key(id: vector.keyId))
            let sealed = try SyncFieldCrypto.seal(bytes(vector.plaintext), purpose: vector.purpose, subject: vector.subject, ring: ring, salt: bytes(vector.salt), nonce: bytes(vector.nonce))
            XCTAssertEqual(sealed.base64EncodedString(), vector.envelope)
            XCTAssertEqual(try SyncFieldCrypto.open(bytes(vector.envelope), purpose: vector.purpose, subject: vector.subject, ring: all), bytes(vector.plaintext))
        }
    }

    func testSlots() throws {
        let vectors = try load()
        for vector in vectors.slots {
            let secret = SymmetricKey(data: bytes(vector.secret))
            let wrapped = try SyncKeyWrap.wrap(bytes(vector.plaintext), secret: secret, userId: vectors.userId, slotId: vector.slotId, kind: vector.kind,
                                               keyId: vector.keyId, salt: bytes(vector.salt), nonce: bytes(vector.nonce))
            XCTAssertEqual(wrapped.base64EncodedString(), vector.wrappedKey, vector.kind)
            XCTAssertEqual(try SyncKeyWrap.unwrap(bytes(vector.wrappedKey), secret: secret, userId: vectors.userId, slotId: vector.slotId, kind: vector.kind, keyId: vector.keyId),
                           bytes(vector.plaintext))
        }
    }

    func testRecoveryThroughVectorSlots() throws {
        let vectors = try load()
        let ring = try ring(vectors)
        let response = SyncKeysResponse(keyId: 2, keyCheck: vectors.accountKeys[1].keyCheck, slots: vectors.slots.map {
            SyncKeySlot(slotId: $0.slotId, kind: $0.kind, keyId: $0.keyId, params: nil, wrappedKey: $0.wrappedKey, updatedAt: nil)
        })
        let code = vectors.recoveryCodes[0].code
        XCTAssertEqual(try SyncKeyEnrollment.recover(userId: vectors.userId, keys: response, recoveryCode: code), ring)
    }

    func testBlobs() throws {
        let vectors = try load()
        for vector in vectors.blobs {
            let plaintext = seed(vector.plaintextSeed, vector.plaintextLength)
            XCTAssertEqual(SHA256.hash(data: plaintext).map { String(format: "%02x", $0) }.joined(), vector.plaintextSha256)
            let key = try SyncBlobKey(bytes: bytes(vector.key))
            let sealed = try SyncBlobCrypto.seal(plaintext, blobId: vector.blobId, key: key, chunkSize: vector.chunkSize, noncePrefix: bytes(vector.noncePrefix))
            XCTAssertEqual(sealed.base64EncodedString(), vector.blob, vector.blobId)
            XCTAssertEqual(try SyncBlobCrypto.open(bytes(vector.blob), blobId: vector.blobId, key: key), plaintext)
        }
    }

    func testRecoveryCodes() throws {
        for vector in try load().recoveryCodes {
            let recovery = try SyncRecoveryKey(bytes: bytes(vector.key))
            XCTAssertEqual(recovery.code, vector.code)
            XCTAssertEqual(try SyncRecoveryKey(code: vector.code), recovery)
        }
    }
}
